"""Research backtest of the follow-the-winner EGAB-P update.

Paper: https://arxiv.org/abs/2406.00655 and https://doi.org/10.1109/ACCESS.2024.3520389
MATLAB EGAB reference (CC BY 4.0): https://doi.org/10.21227/dxpv-1g10
License metadata: https://api.datacite.org/dois/10.21227/dxpv-1g10
Classical EG reference (Feedback MIT License):
https://github.com/Marigold/universal-portfolios/blob/master/universal/algos/eg.py
https://github.com/Marigold/universal-portfolios/blob/master/universal/algo.py
https://github.com/Marigold/universal-portfolios/blob/master/LICENSE
https://pypi.org/project/universal-portfolios/
OLPS classical EG reference (Apache-2.0): https://github.com/OLPS/OLPS
https://github.com/OLPS/OLPS/blob/master/Strategy/eg_run.m
Classical EG examples reviewed:
https://sudeepraja.github.io/OPS3/
https://github.com/ashegde/online-portfolios-with-multiplicative-updates/blob/main/simulation.py
The NumPy update and open execution are independently implemented.
"""

import gzip
import hashlib
import json
import signal
from collections import deque
from dataclasses import dataclass, fields, replace
from datetime import datetime
from io import BytesIO
from pathlib import Path

import numpy as np
import pandas as pd
import yaml


ROOT = Path(__file__).resolve().parent
PRICE_FIELDS = ["Open", "Close", "Dividends", "Capital Gains", "Stock Splits"]
TRADING_DAYS = 252
DEFORMATION_LIMIT = np.log(1e4)


@dataclass(frozen=True)
class Model:
    alpha: float
    beta: float
    eta: float
    weight_floor: float


@dataclass(frozen=True)
class Execution:
    commission_bps: float
    slippage_bps: float

    @property
    def rate(self):
        return (self.commission_bps + self.slippage_bps) / 10_000


def validate_parameters(model, execution, n_assets):
    if not np.isfinite([model.alpha, model.beta, model.eta, model.weight_floor]).all():
        raise ValueError("Model parameters must be finite.")
    if model.eta <= 0 or not 0 < model.weight_floor < 1 / n_assets:
        raise ValueError("Invalid learning rate or weight floor.")
    if min(execution.commission_bps, execution.slippage_bps) < 0 or not 0 <= execution.rate < 0.5:
        raise ValueError("Fees must be nonnegative and the combined rate below 50% per side.")


def validate_prices(prices, columns, start, end):
    prices = prices.reindex(columns=columns).sort_index()
    if prices.empty or prices.index.has_duplicates or prices.index.hasnans:
        raise ValueError("Missing, duplicate, or invalid market sessions.")
    if prices.index[0] >= start or prices.index[-1] < end - pd.Timedelta(days=7):
        raise ValueError("Price history misses the warm-up session or the end of the sample.")
    first_session = prices.index.searchsorted(start)
    prices = prices.iloc[first_session - 1 :].loc[:end]
    if len(prices) < 3 or prices.index[1] > start + pd.Timedelta(days=7):
        raise ValueError("Price history misses the start of the sample.")
    if not np.isfinite(prices.to_numpy()).all():
        missing = prices.columns[~np.isfinite(prices.to_numpy()).all(axis=0)]
        raise ValueError(f"Incomplete daily history: {missing.tolist()}")
    if (prices[["Open", "Close"]] <= 0).any().any():
        raise ValueError("Nonpositive opening or closing price.")
    return prices


def load_prices(config, tickers, start, end):
    columns = pd.MultiIndex.from_product([PRICE_FIELDS, tickers], names=["Price", "Ticker"])
    cache_key = hashlib.sha256(f"ohlc-actions-v1|{tickers}|{start}|{end}".encode()).hexdigest()[:16]
    name = f"prices_{cache_key}.csv.gz"
    snapshot = config["data"]["snapshots"][name]
    compressed_csv = gzip.decompress(snapshot["gzip"])
    snapshot_sha256 = hashlib.sha256(compressed_csv).hexdigest()
    if snapshot_sha256 != snapshot["sha256"]:
        raise ValueError(f"SHA-256 mismatch for snapshot {name!r}.")

    raw = gzip.decompress(compressed_csv)
    with BytesIO(raw) as file:
        fetched_at = datetime.fromisoformat(file.readline().decode("utf-8").strip())
        frame = pd.read_csv(file, header=[0, 1], index_col=0, parse_dates=True)
    prices = validate_prices(frame, columns, start, end)
    input_sha256 = hashlib.sha256(raw.partition(b"\n")[2]).hexdigest()
    print(
        "Data source: Yahoo Finance (query2.finance.yahoo.com) daily OHLC and corporate actions "
        "via yfinance (auto_adjust=False) embedded in config under data.snapshots "
        f"(decompressed sha256 {snapshot_sha256}); the script does not call yfinance, FRED "
        "or any host and reads no data_cache"
    )
    print(f"Input SHA-256: {input_sha256}")
    print(f"DATA_SHA256: {snapshot_sha256}")
    print("MARKET_DATA_SNAPSHOT: " + json.dumps({
        "path": "config.yaml",
        "key": "data.snapshots",
        "name": name,
        "sha256": snapshot_sha256,
    }))
    return prices, fetched_at.isoformat()


def price_relatives(prices):
    open_prices = prices["Open"].iloc[1:]
    close_prices = prices["Close"]
    # Each ex-date opens on a base determined by its published distribution and the last close.
    # Yahoo's split adjustment already uses the same share basis on both sides of a split.
    distributions = prices["Dividends"] + prices["Capital Gains"]
    prior_base = (close_prices.shift(1) - distributions).iloc[1:]
    if (prior_base <= 0).any().any():
        raise ValueError("Nonpositive previous close after the ex-date adjustment.")
    overnight = open_prices / prior_base
    intraday = close_prices.iloc[1:] / open_prices
    return overnight, intraday


def egab_target(previous_target, drifted_weights, forecast, model, cost_rate):
    weights = np.maximum(previous_target, model.weight_floor)
    weights /= weights.sum()
    trade = weights - drifted_weights
    gradient = -forecast / np.dot(weights, forecast)
    gradient += cost_rate * np.sign(trade) / (1 - cost_rate * np.abs(trade).sum())
    gradient -= gradient.mean()
    gamma = 1 - model.alpha - model.beta
    step = -model.eta * weights**gamma * gradient

    if model.beta == 0:
        log_multiplier = step
    else:
        scaled_step = model.beta * step
        in_domain = scaled_step > -1
        log_multiplier = np.full_like(step, -np.sign(model.beta) * DEFORMATION_LIMIT)
        log_multiplier[in_domain] = np.log1p(scaled_step[in_domain]) / model.beta
    updated = weights * np.exp(np.clip(log_multiplier, -DEFORMATION_LIMIT, DEFORMATION_LIMIT))

    if updated.sum() > 1:
        # Euclidean simplex projection: subtract the threshold on the positive support.
        ranked = np.sort(updated)[::-1]
        offsets = (ranked.cumsum() - 1) / np.arange(1, len(ranked) + 1)
        threshold = offsets[ranked > offsets][-1]
        updated = np.maximum(updated - threshold, 0)
    return updated / updated.sum()


def fill_at_open(open_values, cash, target, rate):
    """Find the largest target allocation funded by opening cash and sale proceeds."""
    opening_value = open_values.sum() + cash

    def remaining_cash(invested):
        changes = target * invested - open_values
        buys = changes[changes > 0].sum()
        sells = -changes[changes < 0].sum()
        return cash + sells * (1 - rate) - buys * (1 + rate)

    low, high = 0.0, opening_value
    for _ in range(44):
        middle = (low + high) / 2
        if remaining_cash(middle) >= 0:
            low = middle
        else:
            high = middle

    filled_values = target * low
    cash = remaining_cash(low)
    if cash < 0:
        raise RuntimeError("Opening fills require more cash than is available.")
    traded = np.abs(filled_values - open_values)
    n_trades = np.count_nonzero(traded > opening_value * 1e-10)
    return filled_values, cash, traded.sum() / opening_value, n_trades


def simulate(overnight, intraday, model, execution, lag_sessions):
    gap_moves = overnight.to_numpy()
    day_moves = intraday.to_numpy()
    n_assets = overnight.shape[1]
    current_target = np.full(n_assets, 1 / n_assets)
    positions = np.zeros(n_assets)
    cash = 1.0
    previous_value = 1.0
    rate = execution.rate
    pending = deque()
    daily_results = []

    for i, (gap, daytime) in enumerate(zip(gap_moves, day_moves, strict=True)):
        positions = positions * gap
        turnover = 0.0
        n_trades = 0
        target = current_target if i == 0 else None
        if pending and pending[0][0] == i:
            _, target = pending.popleft()
        if target is not None:
            positions, cash, turnover, n_trades = fill_at_open(positions, cash, target, rate)
            current_target = target

        positions = positions * daytime
        close_value = positions.sum() + cash
        daily_results.append((close_value / previous_value - 1, turnover, n_trades))
        previous_value = close_value

        if model is not None and i + lag_sessions < len(gap_moves):
            forecast = gap * daytime
            drifted_weights = positions / positions.sum()
            signal_target = egab_target(current_target, drifted_weights, forecast, model, rate)
            pending.append((i + lag_sessions, signal_target))

    return pd.DataFrame(daily_results, index=overnight.index,
                        columns=["return", "turnover", "n_trades"])


def metrics(daily_results, risk_free):
    returns = daily_results["return"]
    excess = returns - risk_free.loc[returns.index]
    growth = np.concatenate(([1.0], np.cumprod(1 + returns.to_numpy())))
    drawdown = growth / np.maximum.accumulate(growth) - 1
    daily_vol = returns.std(ddof=1)
    excess_vol = excess.std(ddof=1)
    return {
        "cagr": float(growth[-1] ** (TRADING_DAYS / len(returns)) - 1),
        "ann_vol": float(daily_vol * np.sqrt(TRADING_DAYS)),
        "sharpe": float(np.sqrt(TRADING_DAYS) * returns.mean() / daily_vol) if daily_vol > 0 else None,
        "sharpe_excess": float(np.sqrt(TRADING_DAYS) * excess.mean() / excess_vol) if excess_vol > 0 else None,
        "max_drawdown": float(drawdown.min()),
        "total_return": float(growth[-1] - 1),
        "turnover": float(daily_results["turnover"].mean() * TRADING_DAYS),
        "n_trades": int(daily_results["n_trades"].sum()),
    }


def main():
    with (ROOT / "config.yaml").open(encoding="utf-8") as config_file:
        config = yaml.safe_load(config_file)
    universe = config["universe"]
    cash_proxy = config["risk_free_ticker"]
    tickers = universe + [cash_proxy]
    if not universe or len(set(tickers)) != len(tickers):
        raise ValueError("Specify a nonempty universe and distinct tickers including the cash proxy.")
    start, is_end, end = (pd.Timestamp(config[key]) for key in ("start", "is_end", "end"))
    lag = config["lag_sessions"]
    if not start < is_end < end or type(lag) is not int or lag < 1:
        raise ValueError("Dates must be ordered and lag_sessions must be a positive integer.")
    model = Model(**config["model"])
    execution = Execution(**config["execution"])
    validate_parameters(model, execution, len(universe))

    prices, fetched_at = load_prices(config, tickers, start, end)
    overnight, intraday = price_relatives(prices)
    risk_free = overnight[cash_proxy] * intraday[cash_proxy] - 1
    risk_free.iloc[0] = intraday[cash_proxy].iloc[0] - 1
    overnight = overnight[universe]
    intraday = intraday[universe]
    is_overnight = overnight.loc[:is_end]
    is_intraday = intraday.loc[:is_end]
    if len(is_overnight) < lag + 2 or len(overnight) - len(is_overnight) < 2:
        raise ValueError("Insufficient sessions for the configured lag and sample split.")

    print(f"DATA_FETCHED_AT: {fetched_at}")
    print("PRICE_ADJUSTMENT: yfinance split-adjusted OHLC with causal ex-date total-return factors")
    print(f"SPLIT_EVENTS: {int(prices['Stock Splits'].ne(0).sum().sum())}")
    print("ROBUSTNESS (IS only):")
    trials = 0
    model_keys = {field.name for field in fields(Model)}
    execution_keys = {field.name for field in fields(Execution)}
    for variant in config["robustness_is"]:
        unknown = variant.keys() - model_keys - execution_keys - {"name"}
        if unknown:
            raise ValueError(f"Unknown robustness settings: {sorted(unknown)}")
        variant_model = replace(model, **{k: variant[k] for k in model_keys & variant.keys()})
        variant_execution = replace(execution, **{k: variant[k] for k in execution_keys & variant.keys()})
        validate_parameters(variant_model, variant_execution, len(universe))
        variant_run = simulate(is_overnight, is_intraday, variant_model, variant_execution, lag)
        variant_metrics = metrics(variant_run, risk_free.loc[:is_end])
        print(f"  {variant['name']}: {json.dumps(variant_metrics, allow_nan=False)}")
        trials += 1

    official = simulate(overnight, intraday, model, execution, lag)
    trials += 1
    benchmark = simulate(overnight, intraday, None, execution, lag)
    official_is = official.loc[:is_end]
    official_oos = official.loc[official.index > is_end]
    result = {
        "strategy": config["strategy"],
        "data_range": {"start": official.index[0].date().isoformat(),
                       "end": official.index[-1].date().isoformat()},
        "is": metrics(official_is, risk_free),
        "oos": metrics(official_oos, risk_free),
        "full": metrics(official, risk_free),
        "benchmark": metrics(benchmark, risk_free),
    }
    print(f"PARAM_COMBOS_TRIED: {trials}")
    for key in ("is", "oos", "full", "benchmark"):
        print(f"{key.upper()}: {json.dumps(result[key], allow_nan=False)}")
    print(f"BENCHMARK_OOS: {json.dumps(metrics(benchmark.loc[official_oos.index], risk_free), allow_nan=False)}")
    print("RESULTS_JSON: " + json.dumps(result, allow_nan=False))


if __name__ == "__main__":
    signal.alarm(14 * 60)
    main()
